export function makeLayer(type,props={}){return {id:uid(),type,name:type==='text'?'Текст':'Изображение',x:5,y:5,w:40,h:12,rotation:0,opacity:1,visible:true,locked:false,color:'#f2efe3',font:'Arial',size:3,bold:false,fontWeight:0,fontStretch:100,italic:false,uppercase:false,smallcaps:false,align:'left',lineHeight:1.2,spacing:0,outline:0,outlineColor:'#000000',shadow:0,shadowColor:'#000000',autoFit:true,tintMode:'none',blendMode:'normal',tintColor:'#ffffff',fit:'slice',imageTile:false,tileWidth:0,tileHeight:0,blur:0,cropZoom:1,cropX:0,cropY:0,cropRotation:0,flipX:false,flipY:false,text:'',...props}}
export function createProject(){const p={version:2,title:'Новый проект',data:{artist:'fakemink',album:'London’s Saviour',note:'© etna vera vela',stereo:'STEREO',lyrics:'',production:'',url:'',A:parseTracks('Kill Everything (3:07)\nPhantas-Ma-Goria (1:26)\nJust Kitten (3:18)\nAir Head (1:17)\nFleeting Feeling (0:50)'),B:parseTracks('London Life (3:33)\nLoser Monologue (3:05)\nCelebrity Deathmatch (3:02)\nOne More, Then I’ll Sleep (1:39)')},layout:{panels:4,flap:25.4,spine:12.7,front:65.1,height:101.6,flapShape:'standard',double:false,columns:1,columnHeight:100,...CASSETTE_TEMPLATE,sync:true},settings:{bg:'#131139',fg:'#f2efe3',accent:'#c4d88b',bgInside:'#f3efdf',bgB:'#131139',numbers:true,durations:true,artists:false,bullets:true,sideA:'A',sideB:'B',sideText:'SIDE',capacity:45,grid:true,guides:true,snap:false,lockDesign:true,autoAlbumColors:true,units:'mm',bleed:2,dpi:300,paper:'a4',copies:1,duplexFlip:'long'},surfaces:{},fonts:[],uploads:[]};resetSurfaces(p);return p}
export function dimensions(p,surface){return surface.startsWith('label')?cassetteDimensions(p.layout):{w:panelRects(p).reduce((n,r)=>n+r.w,0),h:p.layout.height}}
export function panelRects(p,surface='outer'){const l=p.layout,widths=l.panelWidths?.length>=l.panels?l.panelWidths.slice(0,l.panels):[l.flap,l.spine,...Array(l.panels-2).fill(l.front)];let x=0;const rects=widths.map((w,i)=>{const r={x,w,index:i,name:i===0?'Клапан':i===1?'Корешок':i===2?'Обложка':'Панель '+(i-1)};x+=w;return r});return surface==='inner'&&l.referenceTemplate?rects.map(r=>({...r,x:x-r.x-r.w})).reverse():rects}

export function resetSurfaces(p){const {flap,spine,front,height,labelW:W,labelH:H}=p.layout,F=flap+spine;const t=(source,x,y,w,h,size,more={})=>makeLayer('text',{name:({artist:'Исполнитель',album:'Альбом',A:'Треки A',B:'Треки B',spine:'Корешок',note:'Подпись',lyrics:'Тексты песен',production:'Выходные данные',stereo:'Стерео',side:'Сторона'})[source]||source,source,x,y,w,h,size,color:p.settings.fg,...more});
p.surfaces.outer=[t('artist',F+5,8,front-10,10,4),t('album',F+5,25,front-10,50,8,{font:'Georgia',bold:true}),t('note',F+5,height-12,front-10,8,2.3),t('spine',flap+spine/2+2,5,height-10,5,3,{rotation:90}),t('A',2,7,flap-4,39,2.5),t('B',2,height/2+3,flap-4,39,2.5)];
if(p.layout.panels>3)p.surfaces.outer.push(t('production',F+front+4,7,front-8,height-14,2.8));p.surfaces.inner=panelRects(p).filter((_,i)=>i>=2).map((r,i)=>t('lyrics',r.x+4,7,r.w-8,height-14,2.8,{name:'Тексты · панель '+(i+1),color:'#252625',flowIndex:i}));
const sx=W/251.16,sy=H/118.43;const labels=()=>[t('artist',6*sx,10*sy,239.16*sx,14*sy,10*sy,{align:'center',bold:true}),t('album',6*sx,(102.43-6.3)*sy,239.16*sx,10*sy,7*sy,{align:'center'}),t('sideText',218.16*sx,55.5*sy,22*sx,6*sy,5*sy,{name:'Префикс стороны',align:'center',uppercase:true,spacing:.6*sx}),t('side',218.16*sx,60.3*sy,22*sx,16*sy,13*sy,{bold:true,align:'center'}),t('tracks',6*sx,24*sy,239.16*sx,20*sy,5.2*sy,{align:'center',lineHeight:1.3}),t('note',6*sx,105.1*sy,239.16*sx,7*sy,3.7*sy,{align:'center'}),t('stereo',5*sx,56*sy,28*sx,10*sy,3.7*sy,{visible:false})];p.surfaces.labelA=labels();p.surfaces.labelB=labels();const area=cassettePrintArea(p.layout.printArea);p.layout.printArea='label';setCassettePrintArea(p,area)}
export function boundText(p,l,surface){if(!l.source)return l.text||'';const d=p.data,st={...p.settings,...(l.trackOptions||{})};const side=surface==='labelB'?'B':'A';if(l.source==='spine')return l.referenceSpine?[!l.hideArtist&&d.artist,!l.hideAlbum&&d.album].filter(Boolean).join(l.spineTwoLines?'\n':' '+(st.referenceSeparator??'-')+' '):l.spineAlbumOnly?d.album:d.artist+' / '+d.album;if(l.source==='referenceHeading')return [!l.hideArtist&&d.artist,!l.hideAlbum&&d.album].filter(Boolean).join(' '+(st.referenceSeparator??'-')+' ');if(l.source==='referenceContents')return [boundText(p,{...l,source:'referenceHeading'},surface),...['A','B'].filter(side=>!l['hide'+side]).map(source=>boundText(p,{...l,source,trackOptions:{...l.trackOptions,showProduction:false}},surface)),d.lyrics,st.showProduction!==false&&d.production].filter(Boolean).join('\n\n');if(l.source==='flapProduction')return d.production||'';if(l.source==='flapTracks'){const showProduction=st.showProduction&&!l.referenceFlapProductionSeparate;if(st.hideTracks)return showProduction?d.production||'':'';const body=['A','B'].map(side=>boundText(p,{...l,source:side,trackOptions:{...l.trackOptions,showProduction:false}},surface)).join('\n\n');return body+(showProduction&&d.production?'\n\n'+d.production:'')}if(l.source==='side')return st['side'+side];if(l.source==='sideText')return st.sideText;if(['A','B','tracks'].includes(l.source)){if(st.hideTracks)return st.showProduction?p.data.production||'':'';const which=l.source==='tracks'?side:l.source;const str=d[which].map((t,i)=>`${st.numbers?(i+1)+'. ':''}${t.title}${st.artists&&t.artist?' — '+t.artist:''}${st.durations&&t.seconds?' ('+time(t.seconds)+')':''}`);const body=l.source==='tracks'?str.join(st.bullets?' · ':'  '):(st.showSide===false?'':st.sideText+' '+st['side'+which]+'\n\n')+str.join(st.inlineTracks?(st.bullets?' · ':'  '):'\n');return body+(st.showProduction&&d.production?'\n\n'+d.production:'')}return d[l.source]||''}
export function migrate(v){if(v.version===2)return validateProject(v);const p=createProject();for(const k of ['artist','album','note'])if(typeof v[k]==='string')p.data[k]=v[k];if(v.tracksA)p.data.A=parseTracks(v.tracksA);if(v.tracksB)p.data.B=parseTracks(v.tracksB);for(const k of ['bg','fg','accent'])if(v[k])p.settings[k]=v[k];for(const k of ['flap','spine','front','height','labelW','labelH'])if(Number.isFinite(v[k]))p.layout[k]=v[k];p.layout.panels=3;resetSurfaces(p);if(/^data:image\//.test(v.art||''))p.surfaces.outer.unshift(makeLayer('image',{name:'Обложка',src:v.art,x:p.layout.flap+p.layout.spine,y:0,w:p.layout.front,h:p.layout.height}));return validateProject(p)}
export function validateProject(v){if(!v||!v.data||!v.layout||!v.surfaces)throw Error('Неверный формат проекта');const p=clone(v),base=createProject(),d=p.data;p.settings={...base.settings,...p.settings};p.layout={...base.layout,holeOffsetX:0,...p.layout};p.layout.printArea=cassettePrintArea(p.layout.printArea);p.title=String(p.title||'Проект').slice(0,200);if(p.libraryId&&!/^[a-z0-9-]{8,80}$/i.test(p.libraryId))delete p.libraryId;for(const k of ['bg','bgB','bgInside','fg','accent'])p.settings[k]=normalizePaint(p.settings[k],base.settings[k]);for(const k of ['artist','album','note','stereo','lyrics','production','url'])d[k]=String(d[k]||'').slice(0,100000);for(const side of ['A','B']){if(!Array.isArray(d[side]))throw Error('Нет треков');d[side]=d[side].slice(0,2000).map(t=>({id:uid(),title:String(t.title||'').slice(0,1000),artist:String(t.artist||'').slice(0,500),seconds:clamp(t.seconds,0,86400),sourcePath:String(t.sourcePath||'').slice(0,8192)}))}const limits={panels:[3,8],flap:[10,70],spine:[6.35,25.4],front:[50,90],height:[80,130],labelW:[70,110],labelH:[30,65],holeW:[0,95],holeH:[0,35],holeY:[0,50],holeOffsetX:[-40,40],columns:[1,2],columnHeight:[20,100]};for(const [k,[a,b]]of Object.entries(limits))p.layout[k]=clamp(p.layout[k],a,b);p.layout.panels=Math.round(p.layout.panels);if(Array.isArray(p.layout.panelWidths)&&p.layout.panelWidths.length===8&&p.layout.panelWidths.every(w=>Number.isFinite(w)&&w>=6&&w<=90)){p.layout.panelWidths=p.layout.panelWidths.map(w=>clamp(w,6,90));p.layout.panelWidths[0]=p.layout.flap;p.layout.panelWidths[1]=p.layout.spine;p.layout.panelWidths[2]=p.layout.front}else delete p.layout.panelWidths;p.fonts=(p.fonts||[]).filter(f=>/^data:font\/(ttf|otf|woff2?);base64,[A-Za-z0-9+/=]+$/.test(f.data||'')).slice(0,80).map(f=>({...f,weight:clamp(f.weight||400,100,900),style:f.style==='italic'?'italic':'normal',name:String(f.name).replace(/[^\w -]/g,'')}));p.uploads=(p.uploads||[]).filter(f=>/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(f.src||'')).slice(0,30);for(const surface of ['outer','inner','labelA','labelB']){if(!Array.isArray(p.surfaces[surface]))throw Error('Нет макетов');p.surfaces[surface]=p.surfaces[surface].slice(0,200).map(l=>{if(!['text','image','shape','qr','barcode'].includes(l.type))throw Error('Неизвестный слой');const o=makeLayer(l.type,l);o.id=uid();o.panelTargets=Array.isArray(o.panelTargets)?[...new Set(o.panelTargets.filter(n=>Number.isInteger(n)&&n>=0&&n<8))]:[];if(o.trackOptions&&typeof o.trackOptions!=='object')delete o.trackOptions;for(const k of ['x','y','rotation'])o[k]=clamp(o[k],-2000,2000);for(const k of ['w','h'])o[k]=clamp(o[k],.1,1500);o.blendMode=IMAGE_BLEND_MODES.includes(o.blendMode)?o.blendMode:'normal';o.imageTile=!!o.imageTile;o.tileWidth=clamp(o.tileWidth||o.w,.1,1500);o.tileHeight=clamp(o.tileHeight||o.h,.1,1500);o.blur=clamp(o.blur,0,20);o.cropZoom=clamp(o.cropZoom||1,.1,10);o.cropX=clamp(o.cropX,-1000,1000);o.cropY=clamp(o.cropY,-1000,1000);o.cropRotation=clamp(o.cropRotation,-360,360);o.size=clamp(o.size,.1,100);o.fontWeight=o.fontWeight?clamp(o.fontWeight,100,900):0;o.fontStretch=clamp(o.fontStretch||100,50,200);o.opacity=clamp(o.opacity,0,1);o.lineHeight=clamp(o.lineHeight,.5,4);o.spacing=clamp(o.spacing,-1,10);o.outline=clamp(o.outline,0,2);o.shadow=clamp(o.shadow,0,5);o.radius=clamp(o.radius,0,50);o.strokeWidth=clamp(o.strokeWidth||.6,.1,20);for(const k of ['color','outlineColor','shadowColor','tintColor']){if(k==='color'&&['text','qr','barcode'].includes(o.type))o[k]=normalizePaint(o[k]);else if(!/^#[a-f0-9]{6}$/i.test(o[k]))o[k]='#000000'};if(o.type==='image'&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(o.src||''))o.src='';return o})}sanitizeReferenceFlowArchive(p);sanitizeReferenceFreePlace(p);return p}
